//! Differential parity tests for `pi_js::vendor::jsdiff`, focused on the call shapes pi uses:
//! `diffLines(old, new)` and `createTwoFilesPatch(path, path, old, new, undefined, undefined,
//! { context, headerOptions: FILE_HEADERS_ONLY })` (core/tools/edit-diff.ts), `diffWords(old, new)`
//! (modes/interactive/components/diff.ts) and `applyPatch(source, patch)` (tools.test.ts), plus
//! option variants, fuzz-factor patch fitting and hand-written edge-case patches.
//!
//! `VECTORS` were generated by running the real `diff@8.0.4` (libesm) under Node 24 on seeded-random
//! and hand-written inputs. Change arrays are compared as `JSON.stringify` output (byte-exact,
//! including key order); patch text, applied text, `false` results and exception messages are
//! compared verbatim.

use pi_js::vendor::jsdiff::{
    ApplyPatchOptions, Change, CreatePatchOptions, DiffLinesOptions, DiffWordsOptions, FILE_HEADERS_ONLY,
    StructuredPatch, apply_patch, create_two_files_patch, diff_lines, diff_words, parse_patch,
};
use serde_json::{Map, Value, json};

fn jnum(n: f64) -> Value {
    if n.is_finite() && n.fract() == 0.0 {
        json!(n as i64)
    } else {
        json!(n)
    }
}

// The JSON shape `parsePatch` returns (`undefined` fields omitted, as `JSON.stringify` does).
fn patch_to_json(p: &StructuredPatch) -> Value {
    let mut m = Map::new();
    let mut put = |k: &str, v: &Option<String>| {
        if let Some(v) = v {
            m.insert(k.to_string(), json!(v));
        }
    };
    put("index", &p.index);
    put("oldFileName", &p.old_file_name);
    put("oldHeader", &p.old_header);
    put("newFileName", &p.new_file_name);
    put("newHeader", &p.new_header);
    let hunks: Vec<Value> = p
        .hunks
        .iter()
        .map(|h| {
            json!({
                "oldStart": jnum(h.old_start),
                "oldLines": jnum(h.old_lines),
                "newStart": jnum(h.new_start),
                "newLines": jnum(h.new_lines),
                "lines": h.lines,
            })
        })
        .collect();
    m.insert("hunks".to_string(), Value::Array(hunks));
    Value::Object(m)
}

fn opt_bool(o: &Value, key: &str) -> Option<bool> {
    o.get(key).and_then(Value::as_bool)
}

fn js_changes(changes: &[Change]) -> Value {
    Value::String(serde_json::to_string(changes).expect("serialize"))
}

/// Runs one case; returns `{"js": ...}`, `{"r": ...}` or `{"err": message}` like the vector.
fn run(case: &Value) -> Value {
    let k = case["k"].as_str().expect("k");
    let s = |key: &str| case[key].as_str().expect(key);
    let o = &case["o"];
    match k {
        "diffLines" => {
            let options = (!o.is_null()).then(|| DiffLinesOptions {
                ignore_whitespace: opt_bool(o, "ignoreWhitespace"),
                strip_trailing_cr: opt_bool(o, "stripTrailingCr"),
                newline_is_token: opt_bool(o, "newlineIsToken"),
                ignore_newline_at_eof: opt_bool(o, "ignoreNewlineAtEof"),
                one_change_per_token: opt_bool(o, "oneChangePerToken"),
            });
            json!({ "js": js_changes(&diff_lines(s("a"), s("b"), options)) })
        }
        "diffWords" => {
            let options = (!o.is_null()).then(|| DiffWordsOptions {
                ignore_case: opt_bool(o, "ignoreCase"),
                one_change_per_token: opt_bool(o, "oneChangePerToken"),
                ..Default::default()
            });
            json!({ "js": js_changes(&diff_words(s("a"), s("b"), options)) })
        }
        "createTwoFilesPatch" => {
            let path = s("path");
            let patch = create_two_files_patch(
                path,
                path,
                s("a"),
                s("b"),
                None,
                None,
                Some(CreatePatchOptions {
                    context: case["context"].as_f64(),
                    header_options: Some(FILE_HEADERS_ONLY),
                    ..Default::default()
                }),
            );
            json!({ "r": patch })
        }
        "applyPatch" => {
            let options = (!o.is_null()).then(|| ApplyPatchOptions {
                fuzz_factor: o.get("fuzzFactor").and_then(Value::as_f64),
                ..Default::default()
            });
            match apply_patch(s("source"), s("patch"), options) {
                Ok(Some(text)) => json!({ "r": text }),
                Ok(None) => json!({ "r": false }),
                Err(e) => json!({ "err": e.to_string() }),
            }
        }
        "parsePatch" => match parse_patch(s("patch")) {
            Ok(list) => json!({ "r": list.iter().map(patch_to_json).collect::<Vec<_>>() }),
            Err(e) => json!({ "err": e.to_string() }),
        },
        other => panic!("unknown case kind {other}"),
    }
}

fn expected(case: &Value) -> Value {
    let mut m = Map::new();
    for key in ["js", "r", "err"] {
        if let Some(v) = case.get(key) {
            m.insert(key.to_string(), v.clone());
        }
    }
    Value::Object(m)
}

#[test]
fn pi_call_shapes_match_jsdiff() {
    let cases: Vec<Value> = serde_json::from_str(VECTORS).expect("vectors");
    assert!(cases.len() > 1000);
    let mut failures = Vec::new();
    for (i, case) in cases.iter().enumerate() {
        let actual = run(case);
        if actual != expected(case) {
            failures.push(format!("case {i}: {case}\n  rust: {actual}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

#[test]
fn edit_tool_round_trip() {
    // tools.test.ts: `applyPatch(originalContent, result.details.patch)` restores the edited text.
    let original = "Hello, world!";
    let edited = "Hello, testing!";
    let patch = create_two_files_patch(
        "test.txt",
        "test.txt",
        original,
        edited,
        None,
        None,
        Some(CreatePatchOptions {
            context: Some(4.0),
            header_options: Some(FILE_HEADERS_ONLY),
            ..Default::default()
        }),
    );
    assert_eq!(
        patch,
        "--- test.txt\n+++ test.txt\n@@ -1,1 +1,1 @@\n-Hello, world!\n\\ No newline at end of file\n+Hello, testing!\n\\ No newline at end of file\n"
    );
    assert_eq!(
        apply_patch(original, patch.as_str(), None).expect("apply"),
        Some(edited.to_string())
    );
}

#[test]
fn large_identical_prefix_does_not_overflow() {
    // Long component chains are built and dropped without recursion.
    let mut a = String::new();
    for i in 0..200_000 {
        a.push_str(&format!("{i}\n"));
    }
    let b = format!("{a}tail\n");
    let changes = diff_lines(&a, &b, None);
    assert_eq!(changes.len(), 2);
    assert_eq!(changes[0].count, 200_000);
    assert!(changes[1].added && changes[1].value == "tail\n");
    let words_a = "w ".repeat(50_000);
    let words_b = format!("{words_a}x");
    let changes = diff_words(
        &words_a,
        &words_b,
        Some(DiffWordsOptions {
            one_change_per_token: Some(true),
            ..Default::default()
        }),
    );
    assert_eq!(changes.len(), 50_001);
}

